write(1,"arterial-line-care",dict(title="Arterial line care", category="vascular-access", topic_drafts=["D02-T04"],
 evidence_status="partial", license_status="permission_required",
 sources=[src(CDC,"full","infection-prevention recommendations for pressure-monitoring systems (2011, last update 2017)"),src("S-ESICM-SHOCK-2014","full","indication in shock (dated)"),src("S-ERC-PRC-2025","full","arterial line after cardiac arrest (paraphrase only; commercial use needs ERC agreement)"),src("S-SSC-2026","partial","recommendation page only"),src("S-SSC-2021","full","complication rates (superseded edition)"),src("S-NCSBN-DELEG-2019","full","delegation principles"),src("S-AHRQ-TS","partial","SBAR page")],
 objectives=["State when guidelines support an arterial catheter.","Describe how to protect the patient from infection, bleeding, limb ischaemia and accidental disconnection.","List the CDC maintenance recommendations for the pressure-monitoring system.","Recognise warning signs and escalate promptly.","Identify which technical steps are not covered by any source read and follow local policy."],
 prerequisites=["Hand hygiene and aseptic technique (SK-21)","Arterial blood pressure fundamentals"],
 sections={
  "indications":sec("partial",it("ESICM 2014: arterial and central venous catheters in shock not responsive to initial therapy and/or needing a vasopressor infusion (ungraded best practice).","partial","S-ESICM-SHOCK-2014"),it("SSC 2026 (recommendation page): either invasive or non-invasive blood-pressure monitoring in septic shock; invasive advised for intermediate-to-high-dose, escalating or multiple vasopressors, frequent arterial sampling, or inconsistent non-invasive readings. SSC 2021's invasive-over-non-invasive suggestion is superseded.","partial","S-SSC-2026","S-SSC-2021"),it("ERC-ESICM 2025: all post-cardiac-arrest patients are monitored with an arterial line.","sourced","S-ERC-PRC-2025")),
  "safety":sec("full",it("Keep all components of the pressure-monitoring system sterile (CDC Category IA).","sourced",CDC),it("Do not give dextrose-containing solutions or parenteral nutrition through the pressure-monitoring circuit (CDC IA).","sourced",CDC),it("Scrub the diaphragm with an appropriate antiseptic before accessing the system through a diaphragm (CDC IA).","sourced",CDC),it("Prefer a closed continuous-flush system and minimise manipulations and entries (CDC Category II).","sourced",CDC),it("Do not routinely replace arterial catheters to prevent infection; remove as soon as no longer needed (CDC Category II).","sourced",CDC)),
  "responsibilities":sec("partial",it("The nurse maintains the system, checks the site and limb, reports readings and problems, and raises the daily question whether the line is still needed.","partial",CDC),it("Do not inject or infuse through the arterial line unless a protocol allows it; keep the line clearly identified.","partial",CDC)),
  "scope":sec("partial",it("Site, limb and system checks, securement, labelling, reporting and documenting: independent nursing (competence required). Blood sampling, flush set-up, transducer changes and alarm limits: per order or protocol. Insertion, replacement, removal and pressure targets: prescriber decision.","partial","S-NCSBN-DELEG-2019")),
  "equipment":sec("local_protocol",LOCAL("Pressure-monitoring set, transducer, flush solution and pressure bag: use the components and manufacturer instructions approved on your unit."),it("Disposable transducers are preferred over reusable ones (CDC IB).","sourced",CDC)),
  "assessment":sec("partial",it("Check colour, warmth, capillary refill, pulses distal to the catheter, pain, numbness, bleeding or haematoma at the site, and signs of infection.","partial",CDC,"S-SSC-2021")),
  "procedure":sec("local_protocol",LOCAL("Zeroing, levelling, waveform (damping) checks and blood sampling are not described by any source read; follow the manufacturer's instructions and your unit's competency-approved procedure.")),
  "monitoring":sec("partial",it("Arterial pressure and waveform, heart rate, limb perfusion, insertion site, flush system, alarms and line days.","partial","S-ESICM-SHOCK-2014")),
  "escalation":sec("partial",it("Escalate immediately for bleeding or disconnection (apply pressure and call for help), a cold, pale or painful limb, a lost or implausible waveform that cannot be corrected, signs of infection or suspected injection into the line.","partial",CDC,"S-SSC-2021")),
  "complications":sec("partial",it("Limb ischaemia and bleeding occurred in under 1% of radial catheters in a systematic review; haematoma was the most common complication; femoral sites carried higher infection risk (SSC 2021 rationale).","partial","S-SSC-2021")),
  "documentation":sec("local_protocol",LOCAL("Record site and side, insertion date and line day, limb checks, waveform quality, set changeover dates, events and escalation as your unit's documentation standard requires.")),
  "communication":sec("partial",it("Use a structured handover (SBAR) for escalation.","partial","S-AHRQ-TS"))},
 checklist=[c("preparation","Confirm the order or protocol and identify the patient with two identifiers.",False,"local_protocol"),c("assessment","Inspect the site and dressing, and check limb colour, warmth, capillary refill and sensation.",True,"partial",CDC),c("assessment","Trace the tubing from catheter to transducer and confirm every connection and stopcock position.",True,"local_protocol"),c("procedure","Confirm a plausible waveform and that alarms are on with limits set per order or protocol.",False,"local_protocol"),c("procedure","Access the system only when needed, scrubbing the diaphragm first and keeping all components sterile.",True,"sourced",CDC),c("procedure","Give nothing through the arterial line except as an approved protocol allows; never dextrose or parenteral nutrition.",True,"sourced",CDC),c("monitoring","Compare unexpected readings with the patient and a non-invasive reading before acting.",False,"partial","S-SSC-2021"),c("escalation","Apply pressure to bleeding, call for help and report a cold or painful limb or a lost waveform immediately.",True,"partial",CDC),c("documentation","Ask each day whether the line is still needed and record the answer.",False,"sourced",CDC)],
 gaps=["Zeroing, levelling, dynamic-response testing and damping: no source read; needs manufacturer IFU and a licensed procedural source.","Blood-sampling technique, flush pressure and rate, alarm limits: unsourced.","Current transducer-change interval: CDC 2011 states 96 hours; the unit's current policy governs and the guideline is dated.","SSC 2026 full publication not read."],
 permissions=["ERC-ESICM 2025 text: commercial use needs an agreement (paraphrase only).","CDC PDF: no reuse statement on the file; verify before reproducing.","Manufacturer IFUs: reproduction permission required."],
 references=[ref("Guidelines for the Prevention of Intravascular Catheter-Related Infections (2011; last update Oct 2017)","CDC/HICPAC",2011,"https://www.cdc.gov/infection-control/media/pdfs/Guideline-BSI-H.pdf"),ref("Consensus on circulatory shock and hemodynamic monitoring","ESICM",2014,"https://pmc.ncbi.nlm.nih.gov/articles/PMC4239778/"),ref("ERC and ESICM Guidelines 2025 Post-Resuscitation Care","ERC/ESICM",2025,"https://www.erc.edu/media/atqopqm4/gl2025-07-post-resus-e.pdf")]))
