write(2,"central-venous-catheter-care",dict(title="Central venous catheter care", category="vascular-access", topic_drafts=["D06-T05"],
 evidence_status="partial", license_status="permission_required",
 sources=[src(CDC,"full","dressing, hand hygiene and site recommendations (re-read in Phase 7)"),src(SHEA,"full","2022 essential practices"),src("N-INS-STANDARDS","not_read","Infusion Therapy Standards of Practice: copyrighted, not accessed"),src("S-NCSBN-DELEG-2019","full","delegation principles"),src("S-AHRQ-TS","partial","SBAR page")],
 objectives=["Describe the hand hygiene, hub disinfection and dressing practices that reduce bloodstream infection.","Recognise warning signs and escalate promptly.","Explain why daily review of line necessity matters.","Identify where documents disagree and follow the unit policy."],
 prerequisites=["Infection prevention (SK-21)","Hand hygiene and aseptic technique"],
 sections={
  "indications":sec("partial",it("Weigh risks and benefits of a central venous device; use the minimum number of ports or lumens essential for the patient (CDC IB).","sourced",CDC)),
  "safety":sec("full",it("Perform hand hygiene before and after palpating the site and before and after inserting, replacing, accessing, repairing or dressing a catheter (CDC IB).","sourced",CDC),it("Disinfect hubs, needleless connectors and injection ports before every access, and use sterile devices only (CDC IA; SHEA 2022 essential practice).","sourced",CDC,SHEA),it("Cover the site with sterile gauze or a sterile transparent semipermeable dressing (CDC IA); replace a dressing that is damp, loosened or visibly soiled (CDC IB).","sourced",CDC),it("Do not use topical antibiotic ointments or creams on insertion sites except for dialysis catheters (CDC IB).","sourced",CDC),it("Do not submerge the catheter or site in water (CDC IB).","sourced",CDC)),
  "responsibilities":sec("partial",it("Only trained, competent staff handle central lines; report lines that look unnecessary and report any breach of technique.","partial",CDC,SHEA)),
  "scope":sec("partial",it("Site care, dressing and access technique within competence and policy: nursing; deciding to insert, replace or remove the line: prescriber.","partial","S-NCSBN-DELEG-2019")),
  "equipment":sec("local_protocol",LOCAL("Dressing type, antiseptic product, connector-scrub time and set-change interval follow the institution's policy.")),
  "assessment":sec("partial",it("Check the site each shift, and more often if the dressing is a concern; note temperature and haemodynamic trend.","partial",CDC)),
  "procedure":sec("local_protocol",LOCAL("Flushing, locking, blood sampling and dressing-change technique: no source read gives the steps; use the competency-approved unit procedure and the manufacturer's instructions."),it("Short-term CVC dressings: gauze every 2 days (Category II); transparent at least every 7 days (Category IB), except where dislodgement risk outweighs the benefit in children. CDC 2011 chlorhexidine-dressing statements are superseded; SHEA 2022 and CDC 2011 differ in detail.","partial",CDC,SHEA)),
  "monitoring":sec("partial",it("Temperature and haemodynamic trend, site, line days, and set and dressing due dates.","partial",CDC)),
  "escalation":sec("partial",it("Escalate promptly for fever or rigors with a line in place, site changes with systemic signs, instability, suspected disconnection or air entry, or occlusion not resolved by routine checks.","partial",CDC,SHEA)),
  "complications":sec("partial",it("Bloodstream infection and sepsis, septic thrombophlebitis, occlusion, accidental disconnection or air embolism, and skin injury from antiseptics or adhesives.","partial",CDC,SHEA)),
  "errors":sec("partial",it("Accessing a hub without disinfecting it, leaving a wet or loose dressing in place, and keeping a line that is no longer needed.","partial",CDC,SHEA)),
  "documentation":sec("local_protocol",LOCAL("Record site assessment, dressing and set changes with date and reason, necessity review, escalation and who was told, per unit standard.")),
  "communication":sec("partial",it("Use SBAR for escalation.","partial","S-AHRQ-TS"))},
 checklist=[c("preparation","Perform hand hygiene and gather supplies as your unit's procedure specifies.",True,"sourced",CDC),c("assessment","Inspect the site and dressing; check the dressing is dry, intact and dated.",True,"sourced",CDC),c("procedure","Disinfect the hub, connector or port before every access.",True,"sourced",CDC,SHEA),c("procedure","Replace a damp, loose or soiled dressing using the unit's approved technique.",True,"local_protocol"),c("monitoring","Check temperature and the haemodynamic trend, and the due dates for dressing and sets.",False,"partial",CDC),c("escalation","Report fever, rigors, site changes, disconnection or air entry immediately.",True,"partial",CDC),c("documentation","Ask whether the line is still needed and record the answer, the site check and any breach.",False,"partial",CDC,SHEA)],
 gaps=["Dressing and set-change intervals: sources disagree or are dated; the unit policy governs.","Flushing, locking and sampling technique: unsourced.","INS Standards of Practice: not accessed (copyright).","CHG bathing and CHG dressing teaching decision: reviewer question."],
 permissions=["INS Standards: permission required.","CDC PDF: verify reuse terms."],
 references=[ref("Guidelines for the Prevention of Intravascular Catheter-Related Infections (2011; last update Oct 2017)","CDC/HICPAC",2011,"https://www.cdc.gov/infection-control/media/pdfs/Guideline-BSI-H.pdf"),ref("Strategies to prevent CLABSI in acute-care hospitals: 2022 update","SHEA/IDSA/APIC",2022,"https://www.cambridge.org/core/journals/infection-control-and-hospital-epidemiology")]))
