write(3,"peripheral-iv-care",dict(title="Peripheral IV care", category="vascular-access", topic_drafts=[],
 evidence_status="partial", license_status="permission_required",
 sources=[src(CDC,"full","peripheral and midline catheter recommendations (re-read in Phase 7)"),src("N-INS-STANDARDS","not_read","copyrighted, not accessed"),src("S-PVP-META-2026","partial","vasopressor via peripheral line adverse events, summary only")],
 objectives=["Describe infection-prevention practices for peripheral catheters.","Check a peripheral site daily and recognise when to remove the catheter.","Escalate suspected extravasation or infection."],
 prerequisites=["Hand hygiene and aseptic technique (SK-21)"],
 sections={
  "indications":sec("partial",it("Select catheters on the basis of intended purpose and duration, known complications (phlebitis, infiltration) and operator experience (CDC IB).","sourced",CDC),it("When therapy will likely exceed six days, a midline catheter or PICC is preferred to a short peripheral catheter (CDC Category II).","sourced",CDC),it("Avoid steel needles for fluids or medicines that could cause tissue necrosis if they extravasate (CDC IA).","sourced",CDC)),
  "safety":sec("full",it("Hand hygiene before and after palpating the site and before and after inserting, replacing, accessing, repairing or dressing a catheter (CDC IB).","sourced",CDC),it("Clean gloves may be used to insert a peripheral catheter if the site is not touched after skin antiseptic (CDC IC); either clean or sterile gloves when changing a dressing (CDC IC).","sourced",CDC),it("In adults use an upper-extremity site; move a catheter placed in a lower extremity to an upper-extremity site as soon as possible (CDC II).","sourced",CDC)),
  "responsibilities":sec("partial",it("Evaluate the site daily by palpation through the dressing and by inspection if the dressing is transparent; do not remove gauze or opaque dressings if there are no signs of infection (CDC II).","sourced",CDC)),
  "scope":sec("local_protocol",LOCAL("Who may insert, flush and remove peripheral catheters, and what may be given peripherally, is set by local policy and competence.")),
  "equipment":sec("local_protocol",LOCAL("Catheter type, dressing and flush products follow your unit's approved supplies.")),
  "assessment":sec("partial",it("Warmth, tenderness, redness or a palpable venous cord indicate phlebitis; local tenderness or other signs may indicate infection.","sourced",CDC)),
  "procedure":sec("local_protocol",LOCAL("Insertion and flushing technique, securement and medicine compatibility: no source read supports the steps; follow the competency-approved unit procedure.")),
  "monitoring":sec("partial",it("Replacement in adults is not needed more often than every 72-96 hours to reduce infection and phlebitis (CDC IB); no recommendation is made on replacing only when clinically indicated (unresolved issue). Follow current unit policy.","partial",CDC)),
  "escalation":sec("partial",it("Remove a peripheral catheter that shows phlebitis, infection or malfunction (CDC IB) and report the findings; report suspected extravasation of a harmful drug immediately.","partial",CDC,"S-PVP-META-2026")),
  "complications":sec("partial",it("Phlebitis, infiltration, extravasation, catheter-related infection.","partial",CDC)),
  "documentation":sec("local_protocol",LOCAL("Record site checks, dressing and catheter dates, removal reasons and escalation per unit standard."))},
 checklist=[c("preparation","Perform hand hygiene before touching the site or catheter.",True,"sourced",CDC),c("assessment","Palpate through the dressing (or inspect a transparent dressing) for tenderness, warmth, redness or a venous cord.",True,"sourced",CDC),c("assessment","Confirm the catheter is still needed and the site is an upper-extremity site in adults.",False,"sourced",CDC),c("procedure","Flush and administer using the unit's approved technique and compatibility rules.",False,"local_protocol"),c("escalation","Stop the infusion and report suspected extravasation, phlebitis or infection immediately.",True,"partial",CDC,"S-PVP-META-2026"),c("documentation","Record the site check, dressing and catheter dates and any removal reason.",False,"local_protocol")],
 gaps=["Insertion technique, flushing, securement and extravasation first response: no authoritative text accessed.","INS Standards of Practice (the usual professional reference): copyrighted, not accessed.","Vasopressor peripheral-line protocols: only summaries read."],
 permissions=["INS Standards: permission required.","CDC PDF: verify reuse terms."],
 references=[ref("Guidelines for the Prevention of Intravascular Catheter-Related Infections (2011; last update Oct 2017)","CDC/HICPAC",2011,"https://www.cdc.gov/infection-control/media/pdfs/Guideline-BSI-H.pdf")]))
