write(4,"endotracheal-tube-care",dict(title="Endotracheal tube care", category="airway-ventilation", topic_drafts=["D01-T12"],
 evidence_status="partial", license_status="permission_required",
 sources=[src("S-AARC-PVA","full","2024 AARC patient-ventilator assessment CPG (cite only; permission needed to reproduce)"),src("S-SHEA-VAP-2022","full","VAP prevention essential practices"),src("S-ERC-ALS-2025","full","airway guidance (paraphrase only)"),src("S-INTL-PI-2026","partial","abridged pressure-injury guide"),src("S-AHRQ-TS","partial","SBAR page")],
 objectives=["Check and record tube position and securement.","Explain how cuff pressure is measured and why palpation is unreliable.","Describe measures that reduce ventilator-associated complications.","Escalate suspected displacement or obstruction immediately."],
 prerequisites=["Suctioning (SK-06)","Ventilator safety checks (SK-07)"],
 sections={
  "indications":sec("partial",it("Care applies to every patient with an endotracheal tube in place.","partial","S-AARC-PVA")),
  "safety":sec("full",it("Measure cuff pressure with a manometer; palpating the pilot balloon is inaccurate (AARC strong recommendation, high certainty).","sourced","S-AARC-PVA"),it("Do not use continuous cuff-pressure monitoring as a VAP-prevention measure (AARC strong recommendation against; SHEA does not recommend automated or frequent monitoring for VAP prevention). Neither document says intermittent checks should stop.","sourced","S-AARC-PVA","S-SHEA-VAP-2022"),it("Keep the head of the bed raised unless contraindicated, and give mouth care with toothbrushing and no chlorhexidine (SHEA essential practices).","sourced","S-SHEA-VAP-2022")),
  "responsibilities":sec("partial",it("Check and document tube depth marking and securement as often as policy requires and after every move, turn, transfer or procedure; assess skin around the airway device.","partial","S-AARC-PVA","S-INTL-PI-2026"),it("Prevent unplanned extubation: assess agitation, optimise analgesia and sedation per protocol, avoid circuit traction.","partial","S-AARC-PVA")),
  "scope":sec("local_protocol",LOCAL("Who re-secures the tube, measures cuff pressure and changes the tube holder varies by country and unit; follow local policy.")),
  "equipment":sec("local_protocol",LOCAL("Manometer, tube holder and securement products follow unit supplies.")),
  "assessment":sec("partial",it("An appropriate cuff pressure range of 20-30 cmH2O appears in AARC narrative text (not a graded recommendation); there is no consensus on how often to measure. Use the unit target.","partial","S-AARC-PVA")),
  "procedure":sec("local_protocol",LOCAL("Re-securing technique, depth checks and cuff adjustment follow the unit's approved procedure; no source read describes the steps.")),
  "monitoring":sec("partial",it("Tube depth and securement, cuff pressure at policy intervals, SpO2, end-tidal CO2 and waveform, expired tidal volume and airway pressures, secretions, skin and mouth, sedation and agitation.","partial","S-AARC-PVA","S-ERC-ALS-2025")),
  "escalation":sec("partial",it("Escalate immediately for suspected displacement or obstruction, loss of capnography trace, severe desaturation, uncorrectable cuff failure, accidental extubation or new airway bleeding, and call for help.","partial","S-AARC-PVA","S-ERC-ALS-2025")),
  "complications":sec("partial",it("Accidental extubation, endobronchial intubation, obstruction, aspiration around the cuff, tracheal injury from over-inflation, pressure injury of lips, mouth, nose or face, ventilator-associated pneumonia.","partial","S-AARC-PVA","S-SHEA-VAP-2022")),
  "documentation":sec("local_protocol",LOCAL("Record tube size and depth, securement, cuff pressure and time, skin and mouth findings, capnography confirmation, events and escalation per your unit's documentation standard.")),
  "communication":sec("partial",it("Use SBAR to escalate.","partial","S-AHRQ-TS"))},
 checklist=[c("assessment","Confirm the tube depth marking matches the recorded depth and the tube is secure.",True,"partial","S-AARC-PVA"),c("assessment","Confirm a capnography trace and ventilator waveform are present.",True,"partial","S-AARC-PVA","S-ERC-ALS-2025"),c("procedure","Measure cuff pressure with a manometer at the unit interval; do not judge it by feeling the pilot balloon.",True,"sourced","S-AARC-PVA"),c("procedure","Check skin and mouth around the tube and securement.",False,"partial","S-AARC-PVA","S-INTL-PI-2026"),c("monitoring","Keep the head of the bed raised unless contraindicated.",False,"sourced","S-SHEA-VAP-2022"),c("escalation","Call for help at once for suspected displacement, obstruction or loss of the capnography trace.",True,"partial","S-ERC-ALS-2025"),c("documentation","Record depth, securement, cuff pressure and time.",False,"local_protocol")],
 gaps=["Cuff target range and interval: unit decision; AARC range is narrative, not graded.","Securement method, restraint policy, who re-secures: unsourced.","Extubation criteria and cuff-leak tests: out of scope of sources read."],
 permissions=["AARC CPGs: cite only; reproduction needs permission.","ERC text: commercial agreement required.","NPIAP guide: permission required."],
 references=[ref("AARC Clinical Practice Guideline: Patient-Ventilator Assessment","AARC",2024,"https://www.aarc.org/resources/clinical-resources/clinical-practice-guidelines/")]))
