write(6,"suctioning",dict(title="Artificial airway suctioning", category="airway-ventilation", topic_drafts=["D01-T11"],
 evidence_status="partial", license_status="permission_required",
 sources=[src("S-AARC-SUCT","full","AARC 2022 artificial airway suctioning CPG (cite only; permission needed to reproduce)"),src("S-SHEA-VAP-2022","full","closed systems: no VAP recommendation")],
 objectives=["Explain when to suction and why a fixed schedule is not the default.","Describe preoxygenation, event duration and saline use according to the guideline.","Monitor and escalate during and after suctioning."],
 prerequisites=["Endotracheal tube care (SK-04)","Hand hygiene (SK-21)"],
 sections={
  "indications":sec("partial",it("Suction when indicated rather than on a fixed schedule unless unit policy requires one; no adult study of suctioning frequency was found, so the adult as-needed approach rests on the earlier AARC guideline and committee judgment.","partial","S-AARC-SUCT")),
  "safety":sec("partial",it("Preoxygenate adult and paediatric patients before suctioning (evidence level B); an FiO2 about 0.2 above baseline may be enough instead of 1.0; the level is set by unit policy or the clinician.","sourced","S-AARC-SUCT"),it("Do not routinely instil normal saline (evidence level B): it may worsen oxygenation and cause coughing, bronchospasm and rises in heart rate and ICP.","sourced","S-AARC-SUCT"),it("Use sterile technique for open suctioning (evidence level C); either open or closed systems can be used in adults; SHEA 2022 makes no VAP recommendation for closed systems.","sourced","S-AARC-SUCT","S-SHEA-VAP-2022"),it("Keep each event as brief as possible, no longer than 15 seconds (guideline text; the appropriateness score differs between sections).","partial","S-AARC-SUCT")),
  "responsibilities":sec("partial",it("Explain to the patient, give analgesia or sedation per orders when needed, position appropriately, and perform hand hygiene on entering and leaving the area and immediately before open suctioning.","partial","S-AARC-SUCT")),
  "scope":sec("local_protocol",LOCAL("The nurse's role in suctioning varies by country and unit; follow local policy and competence requirements.")),
  "equipment":sec("local_protocol",LOCAL("Suction system, catheter size and suction pressure follow the unit's policy; the catheter-size ratio is inconsistent within the guideline.")),
  "assessment":sec("partial",it("Check SpO2, heart rate, rhythm, ventilator pressures, secretions, and ICP and CPP where monitored.","partial","S-AARC-SUCT")),
  "procedure":sec("local_protocol",LOCAL("Technique steps (depth, withdrawal, passes) follow the unit's approved procedure; the sections read do not specify them.")),
  "monitoring":sec("partial",it("During and after suctioning: SpO2 and heart rate continuously, blood pressure as indicated, ECG rhythm, ventilator pressures and waveform, secretions, comfort and the number and duration of passes.","partial","S-AARC-SUCT")),
  "escalation":sec("partial",it("Stop and escalate for persistent desaturation, instability or arrhythmia, bleeding, suspected tube obstruction or displacement, bronchospasm, ICP rises or secretions that cannot be cleared.","partial","S-AARC-SUCT")),
  "complications":sec("partial",it("Hypoxaemia, arrhythmias, bradycardia, hypotension or hypertension, raised ICP, bleeding and mucosal injury, bronchospasm, atelectasis, infection, pain, accidental extubation or disconnection.","partial","S-AARC-SUCT")),
  "documentation":sec("local_protocol",LOCAL("Record the indication, pre-assessment, preoxygenation, system used, passes and duration, secretions, response and escalation per your unit's documentation standard."))},
 checklist=[c("preparation","Confirm the indication for suctioning and explain to the patient.",False,"partial","S-AARC-SUCT"),c("preparation","Perform hand hygiene and prepare equipment using sterile technique for open suctioning.",True,"sourced","S-AARC-SUCT"),c("preparation","Preoxygenate before suctioning (level per unit policy).",True,"sourced","S-AARC-SUCT"),c("procedure","Limit each suctioning event to as short a time as possible, no longer than 15 seconds.",True,"partial","S-AARC-SUCT"),c("procedure","Do not instil saline routinely.",False,"sourced","S-AARC-SUCT"),c("monitoring","Watch SpO2, heart rate, rhythm and pressures throughout, and afterwards.",True,"partial","S-AARC-SUCT"),c("escalation","Stop and call for help for persistent desaturation, instability, bleeding or suspected obstruction.",True,"partial","S-AARC-SUCT"),c("documentation","Record indication, passes, secretions and the patient's response.",False,"local_protocol")],
 gaps=["Adult as-needed frequency: no adult study found.","Catheter-size ratio and suction pressure: inconsistent or unspecified.","Suctioning in raised ICP and tracheostomy suctioning: not covered."],
 permissions=["AARC CPG: cite only; reproduction needs permission."],
 references=[ref("AARC Clinical Practice Guideline: Artificial Airway Suctioning","AARC",2022,"https://www.aarc.org/resources/clinical-resources/clinical-practice-guidelines/")]))
