write(9,"blood-transfusion",dict(title="Blood transfusion", category="transfusion-nutrition", topic_drafts=["D08-T03"],
 evidence_status="partial", license_status="permission_required",
 sources=[src("S-AABB-COI-2024","partial","US Circular of Information (labelling document, not a nursing guideline): general instructions and side-effect sections read"),src("S-FDA-COI-2024","partial","FDA-recognised acceptable Circular"),src("S-OPENRN-ADV-CH3","partial","Open RN Advanced Skills 3.4 checklist (CC BY, educational textbook)"),src("S-NICE-NG24","partial","NICE NG24 monitoring recommendations"),src("S-BSH-ATR","not_read","BSH acute transfusion reactions guideline: not accessed")],
 objectives=["Verify order, patient identity and the container, and refuse to start if anything does not match.","Describe time limits and tubing rules from the Circular.","Recognise and stop for suspected reactions and escalate."],
 prerequisites=["Patient identification and documentation","Hand hygiene (SK-21)"],
 sections={
  "indications":sec("local_protocol",LOCAL("Indications and thresholds for transfusion are prescriber decisions; this draft does not state thresholds per your unit's documentation standard.")),
  "safety":sec("partial",it("Check the order, patient identity and container as local policy requires; do not start if anything does not match; do not use a product that looks abnormal and contact the transfusion service.","partial","S-AABB-COI-2024","S-OPENRN-ADV-CH3"),it("Do not add medicines or solutions to the tubing or run them through it at the same time, except 0.9% sodium chloride unless approved; never use lactated Ringer's or other calcium-containing solutions with citrate-containing components (Circular).","partial","S-AABB-COI-2024"),it("Entering the container breaks the system: complete the transfusion within 4 hours of entry (Circular).","partial","S-AABB-COI-2024"),it("Use a sterile clot filter as the Circular describes and local policy requires; warm blood only when clinically indicated with a cleared warming device.","partial","S-AABB-COI-2024")),
  "responsibilities":sec("partial",it("Use aseptic technique, monitor the patient as policy requires, and stop the transfusion and inform the team at the first sign of a reaction.","partial","S-AABB-COI-2024","S-NICE-NG24")),
  "scope":sec("local_protocol",LOCAL("Who may check, start and monitor transfusions is set by local policy and competence.")),
  "equipment":sec("local_protocol",LOCAL("Administration sets, filters and warmers follow the unit's supplies and the manufacturer's instructions.")),
  "assessment":sec("partial",it("Observe the patient before, during and after transfusion at the frequency in local policy (NICE NG24 recommendation 1.13 on monitoring).","partial","S-NICE-NG24")),
  "procedure":sec("local_protocol",LOCAL("Start rate, vital-sign timings and the step sequence follow the transfusion service's procedure; no graded source was read per your unit's documentation standard.")),
  "monitoring":sec("partial",it("Monitor for fever, rigors, breathlessness, rash, hypotension, pain and changes in condition.","partial","S-AABB-COI-2024")),
  "escalation":sec("partial",it("Stop the transfusion, keep access, inform the prescriber and the transfusion service. First-line management beyond this is not drawn from a source read.","partial","S-AABB-COI-2024","S-BSH-ATR")),
  "complications":sec("partial",it("Febrile, allergic, haemolytic and respiratory reactions and bacterial contamination are described in the Circular's side-effect sections.","partial","S-AABB-COI-2024")),
  "documentation":sec("local_protocol",LOCAL("Record product identifiers, checks, times, observations, reactions and actions per unit and transfusion-service standard."))},
 checklist=[c("preparation","Check the order, patient identity and container against each other as local policy requires.",True,"partial","S-AABB-COI-2024","S-OPENRN-ADV-CH3"),c("preparation","Inspect the product; do not use it if it looks abnormal and contact the transfusion service.",True,"partial","S-AABB-COI-2024"),c("procedure","Use aseptic technique and the filter and warmer required by policy.",False,"partial","S-AABB-COI-2024"),c("procedure","Give nothing else through the transfusion tubing except what the Circular allows.",True,"partial","S-AABB-COI-2024"),c("monitoring","Complete the transfusion within 4 hours of entering the container.",True,"partial","S-AABB-COI-2024"),c("monitoring","Observe the patient at the frequency in local policy.",True,"partial","S-NICE-NG24"),c("escalation","Stop the transfusion and inform the team at the first sign of a reaction.",True,"partial","S-AABB-COI-2024"),c("documentation","Record identifiers, times, observations and any reaction.",False,"local_protocol")],
 gaps=["First-line actions after a reaction: BSH guideline not accessed.","Component-specific details: only general sections read.","Non-US jurisdictions: UK, European and other national guidance not read."],
 permissions=["AABB Circular: reproduction permission required.","Open RN: CC BY with attribution; check image licences."],
 references=[ref("Circular of Information for the Use of Human Blood and Blood Components","AABB/ARC/ABC/ASBP",2024,"https://www.aabb.org/news-resources/resources/circular-of-information"),ref("Blood transfusion (NG24)","NICE",2015,"https://www.nice.org.uk/guidance/ng24")]))
